1. **事实**：只写录像能拍到的部分。
2. **感受**：允许焦虑、愤怒、委屈、羞耻、麻木同时存在。
3. **意义**：这件事碰到了我什么担心、需要或价值？
4. **行动**：现在最小、最安全、最可逆的一步是什么？

